#!/usr/bin/env python3
"""Исход поломки в тестах ЧЕЛОВЕКА: поймана, выжила — или прогон не состоялся.

Сценарий пришёл из внешней проверки и переписан здесь регрессионным тестом
ПРАВИЛЬНОГО поведения. Инструмент считал исход одной строкой `caught = rc != 0`,
а команда тестов отвечала одним и тем же кодом на две разные аварии: и когда
она не запустилась вовсе, и когда не уложилась в отведённое время. Обе шли
в зачёт пойманной поломкой.

Здесь это хуже, чем у нашей собственной планки. Планка меряет нас, а этот
инструмент едет людям и доказывает, что ИХ тесты ловят ИХ поломки. Человек
читал «твои тесты ловят подмену» ровно там, где у него не выполнилось ни
одного теста, — то самое враньё умолчанием, против которого инструмент и
написан.

Проект здесь крошечный, и верный ответ в нём известен заранее: проверка читает
`dep.py` и не читает `unused.py`. Подмена в первом обязана быть поймана, во
втором — выжить, а подмена, после которой прогон не завершается, не равна ни
той, ни другой. Обратный контроль стоит здесь столько же, сколько прямой:
починка «объявить неизвестным вообще всё» прошла бы этот файл незамеченной.

Тест самодостаточен: только стандартная библиотека и сам инструмент.
"""
from __future__ import annotations

import importlib.util
import shlex
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]

_спек = importlib.util.spec_from_file_location(
    "ss_prove_tests_verdict",
    РЕПО / "plugins" / "superstack" / "tools" / "prove_tests.py")
pt = importlib.util.module_from_spec(_спек)
_спек.loader.exec_module(pt)

#: Зависимость проекта. Задержка вынесена в неё нарочно: так подмена умеет
#: не только менять ответ, но и подвешивать прогон — вторая авария выглядит
#: для инструмента ровно так же, как первая, и в этом весь дефект.
ЗАВИСИМОСТЬ = "ЗАДЕРЖКА = 0\nЗНАЧЕНИЕ = 1\n"
#: Файл, которого проверка не читает. Подмена в нём обязана ВЫЖИТЬ.
ЛИШНИЙ = "ЛИШНЕЕ = 1\n"
#: Вся «проверка» проекта: падает ненулевым кодом, если значение не то.
#:
#: Зависимость читается ИСХОДНЫМ ТЕКСТОМ, а не импортом. Подмена того же
#: размера в ту же секунду неотличима для инвалидации кэша байткода, и
#: проверка пошла бы по старому `.pyc` — то есть ответ этого теста зависел бы
#: от кэша, а не от исхода поломки. Здесь проверяется вердикт, и мешать в него
#: чужую беду нельзя.
ПРОВЕРКА = ("import time\n\n"
            "данные = {}\n"
            "exec(open('dep.py', encoding='utf-8').read(), данные)\n"
            "time.sleep(данные['ЗАДЕРЖКА'])\n"
            "assert данные['ЗНАЧЕНИЕ'] == 1\n")
#: Команда тестов, которая заведомо не уложится ни в какой разумный предел.
МЕДЛЕННО = "import time\n\ntime.sleep(30)\n"

ЗАВИСАНИЕ = {"id": "проба.зависание", "file": "dep.py",
             "find": "ЗАДЕРЖКА = 0", "replace": "ЗАДЕРЖКА = 30",
             "why": "после подмены прогон не завершается вовсе"}
ЛОВИТСЯ = {"id": "проба.значение", "file": "dep.py",
           "find": "ЗНАЧЕНИЕ = 1", "replace": "ЗНАЧЕНИЕ = 2",
           "why": "подмена, которую проверка обязана поймать"}
ВЫЖИВАЕТ = {"id": "проба.лишнее", "file": "unused.py",
            "find": "ЛИШНЕЕ = 1", "replace": "ЛИШНЕЕ = 2",
            "why": "подмена в файле, который не читает ни одна проверка"}

#: Предел, который держит запас в тридцать раз над запуском интерпретатора и
#: при этом в тридцать раз меньше подвешенного прогона. Числа взяты так, чтобы
#: ответ теста не зависел от того, насколько занята машина.
ПРЕДЕЛ = 1.0


class Проект(unittest.TestCase):
    """Дерево на три файла, где верный исход каждой подмены известен заранее."""

    def setUp(self):
        врем = tempfile.TemporaryDirectory()
        self.addCleanup(врем.cleanup)
        self.корень = Path(врем.name)
        (self.корень / "dep.py").write_text(ЗАВИСИМОСТЬ, encoding="utf-8")
        (self.корень / "unused.py").write_text(ЛИШНИЙ, encoding="utf-8")
        (self.корень / "check.py").write_text(ПРОВЕРКА, encoding="utf-8")
        (self.корень / "slow.py").write_text(МЕДЛЕННО, encoding="utf-8")

    def набор(self, *поломки, cmd: str = None) -> dict:
        по_умолчанию = f"{shlex.quote(sys.executable)} check.py"
        return {"test_cmd": по_умолчанию if cmd is None else cmd,
                "mutations": list(поломки)}

    def медленная_команда(self) -> str:
        return f"{shlex.quote(sys.executable)} slow.py"

    def короткий_предел(self) -> None:
        """Отведённое время, в которое подвешенный прогон заведомо не влезет."""
        прежний = pt.TIMEOUT
        pt.TIMEOUT = ПРЕДЕЛ
        self.addCleanup(setattr, pt, "TIMEOUT", прежний)


class БазовыйПрогонРазличаетТриБеды(Проект):
    """Красный набор, несостоявшийся запуск и сорванное время — не одно и то же.

    Все три означают «исходы читать нельзя», но чинит человек в каждом случае
    разное, поэтому причина обязана называться своими словами.
    """

    def test_не_уложившийся_базовый_прогон_это_неизвестно(self):
        self.короткий_предел()
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ, cmd=self.медленная_команда()))
        self.assertEqual(v["status"], "unknown", v)
        self.assertEqual(v["caught"], 0, v)
        self.assertEqual(v["executed"], 0, v)
        self.assertIn("не уложились", v["detail"])
        self.assertNotIn("поймана", v["detail"])

    def test_несуществующая_команда_называется_другой_причиной(self):
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ, cmd="такой-команды-нет"))
        self.assertEqual(v["status"], "unknown", v)
        self.assertEqual(v["caught"], 0, v)
        self.assertIn("запустить", v["detail"])
        self.assertNotIn("не уложились", v["detail"])

    def test_красный_набор_остаётся_красным_а_не_несостоявшимся(self):
        """Обратный контроль: набор, который ЧЕСТНО упал, — это не авария."""
        (self.корень / "dep.py").write_text("ЗАДЕРЖКА = 0\nЗНАЧЕНИЕ = 9\n",
                                            encoding="utf-8")
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ))
        self.assertEqual(v["status"], "unknown", v)
        self.assertIn("красный ДО поломок", v["detail"])
        self.assertEqual(v["caught"], 0, v)


class ИсходПоломкиТрёхзначен(Проект):
    """Поймана, выжила, прогон не состоялся — и третье не равно первому."""

    def test_подвешенный_прогон_не_считается_пойманной(self):
        self.короткий_предел()
        v = pt.run(self.корень, self.набор(ЗАВИСАНИЕ))
        self.assertEqual([x["id"] for x in v["inconclusive"]],
                         ["проба.зависание"], v)
        self.assertEqual(v["caught"], 0, v)
        self.assertEqual(v["survived"], [], v)
        self.assertEqual(v["status"], "unknown", v)
        self.assertIn("не уложились", v["inconclusive"][0]["why"], v)

    def test_настоящая_поломка_по_прежнему_поймана(self):
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ))
        self.assertEqual(v["status"], "pass", v)
        self.assertEqual((v["caught"], v["executed"]), (1, 1), v)
        self.assertEqual(v["inconclusive"], [], v)

    def test_настоящая_выжившая_по_прежнему_выжившая(self):
        v = pt.run(self.корень, self.набор(ВЫЖИВАЕТ))
        self.assertEqual(v["status"], "fail", v)
        self.assertEqual([s["id"] for s in v["survived"]], ["проба.лишнее"], v)
        self.assertEqual(v["caught"], 0, v)
        self.assertEqual(v["inconclusive"], [], v)


class НеизвестноеНеСчитаетсяНиТемНиДругим(Проект):
    """Ненулевое «неизвестно» — это «проверить не смог», а не «тесты держат»."""

    def test_одна_поймана_одна_не_состоялась_чистого_успеха_нет(self):
        self.короткий_предел()
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ, ЗАВИСАНИЕ))
        self.assertEqual(v["status"], "unknown", v)
        self.assertEqual(v["caught"], 1, v)
        self.assertEqual(v["executed"], 1, v)
        self.assertEqual(len(v["inconclusive"]), 1, v)

    def test_отчёт_называет_четыре_числа(self):
        """Одно громкое число вместо четырёх честных читается как проверка."""
        self.короткий_предел()
        v = pt.run(self.корень, self.набор(ЛОВИТСЯ, ЗАВИСАНИЕ))
        for кусок in ("зарегистрировано 2", "выполнено 1",
                      "поймано 1", "неизвестно 1"):
            self.assertIn(кусок, v["detail"], v)


if __name__ == "__main__":
    unittest.main()
